#include <stdio.h>
int main() {
    int t; if (scanf("%d", &t) != 1) return 0;
    while (t--) {
        long long a, b;
        scanf("%llx %llx", &a, &b);
        printf("%llX\n", a + b);
    }
    return 0;
}

