#include <iomanip>
using namespace std;
int main() {
    int t; if (cin >> t) {
        while (t--) {
            string s1, s2; cin >> s1 >> s2;
            unsigned long long a = stoull(s1, nullptr, 16);
            unsigned long long b = stoull(s2, nullptr, 16);
            stringstream ss;
            ss << hex << uppercase << (a + b);
            cout << ss.str() << "\n";
        }
    }
    return 0;
}

code.Java:
import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int t = sc.nextInt();
            while (t-- > 0) {
                long a = Long.parseLong(sc.next(), 16);
                long b = Long.parseLong(sc.next(), 16);
                System.out.println(Long.toHexString(a + b).toUpperCase());
            }
        }
    }
}

